import brandGen from "@/brand.gen.json";

export interface BrandFederationConfig {
  defaultAddress: string;
  defaultPeer: string;
  /** Built-in identity genesis pin: LAN auto-discovery only connects to this union. */
  genesisHash: string;
}

export interface BrandConfig {
  id: string;
  productName: string;
  shortName: string;
  identifier: string;
  deeplinkScheme: string;
  copyright: string;
  federation: BrandFederationConfig;
}

/**
 * Build-time brand identity, generated by `scripts/brand/apply.js`
 * (source of truth: `brands/<id>/brand.json`). Do not edit `src/brand.gen.json`
 * by hand; on this branch it carries the Folly Launcher brand.
 */
export const brand: BrandConfig = brandGen;
